oxy_webhelp_navlinks = {"manage_agent_operations_policies-d37814e62861":{"topics":[{"title":"How policies work","shortdesc":"<p class=\"shortdesc\">A policy is a named rule with a severity that <span class=\"ph\">Agent Cloud<\/span> evaluates against         your agents, tools, and sessions. When agent activity breaks a policy, <span class=\"ph\">Agent Cloud<\/span> records a violation or an alert and, depending on the policy's         enforcement mode, can stop the action.<\/p>","href":"agent_cloud\/how_policies_work_agent_cloud.html","attributes":{"data-id":"how_policies_work_agent_cloud"},"menu":{"hasChildren":false},"tocID":"how_policies_work_agent_cloud-d37814e62874","next":"how_policies_work_agent_cloud-d37814e62874"},{"title":"Enforcement modes","shortdesc":"<p class=\"shortdesc\">A policy's enforcement mode determines what happens when agent activity breaks it:         Monitor records an alert, Block stops the action before it runs, and Ask hands the action to the         agent's own approval prompt.<\/p>","href":"agent_cloud\/policy_enforcement_types_agent_cloud.html","attributes":{"data-id":"policy_enforcement_types_agent_cloud"},"menu":{"hasChildren":false},"tocID":"policy_enforcement_types_agent_cloud-d37814e62925","next":"policy_enforcement_types_agent_cloud-d37814e62925"},{"title":"How blocking works","shortdesc":"<p class=\"shortdesc\">A Block policy lets <span class=\"ph\">Agent Cloud<\/span> stop an agent action before it takes         effect, inline with the agent's own execution, instead of only flagging it         afterward.<\/p>","href":"agent_cloud\/how_blocking_works_agent_cloud.html","attributes":{"data-id":"how_blocking_works_agent_cloud"},"menu":{"hasChildren":false},"tocID":"how_blocking_works_agent_cloud-d37814e62947","next":"how_blocking_works_agent_cloud-d37814e62947"},{"title":"<span class=\"ph\">Agent Cloud<\/span> system policies","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">Agent Cloud<\/span> includes multiple system policies. These policies are not         enabled by default. You can enable them from the Policies page.<\/p>","href":"agent_cloud\/agent_cloud_system_policies.html","attributes":{"data-id":"agent_cloud_system_policies"},"menu":{"hasChildren":false},"tocID":"agent_cloud_system_policies-d37814e63003","topics":[]},{"title":"<span class=\"ph\">Agent Cloud<\/span> policy packs","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">Agent Cloud<\/span> policy packs are curated collections of system policies you         can add to your <span class=\"ph\">Agent Cloud<\/span> account to enable a focused set of controls for a         specific risk area, compliance framework, or industry.<\/p>","href":"agent_cloud\/policy_packs_agent_cloud.html","attributes":{"data-id":"policy_packs_agent_cloud"},"menu":{"hasChildren":false},"tocID":"policy_packs_agent_cloud-d37814e63018","next":"policy_packs_agent_cloud-d37814e63018"},{"title":"Custom policies","shortdesc":"<p class=\"shortdesc\">A custom policy is a rule that you write in plain English. The Semantic AI Governance         Engine (SAGE) turns it into a policy that it judges against agent activity by intent, not by         matching keywords.<\/p>","href":"agent_cloud\/custom_policies.html","attributes":{"data-id":"custom_policies"},"menu":{"hasChildren":false},"tocID":"custom_policies-d37814e63089","next":"custom_policies-d37814e63089"},{"title":"Alerts and violations","shortdesc":"<p class=\"shortdesc\">Alerts and violations are the findings that your policies produce. An alert is a         specific action or message that broke a policy. A violation is a standing configuration that         breaks one.<\/p>","href":"agent_cloud\/alerts_violations_agent_cloud.html","attributes":{"data-id":"alerts_violations_agent_cloud"},"menu":{"hasChildren":false},"tocID":"alerts_violations_agent_cloud-d37814e63150","next":"alerts_violations_agent_cloud-d37814e63150"},{"title":"Viewing insights","shortdesc":"<p class=\"shortdesc\">View the Insights page to review security recommendations and posture         improvements identified by <span class=\"ph\">Agent Cloud<\/span>.<\/p>","href":"agent_cloud\/viewing_insights.html","attributes":{"data-id":"viewing_insights"},"menu":{"hasChildren":false},"tocID":"viewing_insights-d37814e63194","topics":[]},{"title":"MCP access policies (Early access)","shortdesc":"<p class=\"shortdesc\">An MCP access policy decides which identities can use an MCP server, or a specific tool         on it, through your MCP gateway.<\/p>","href":"agent_cloud\/mcp_access_policies_agent_cloud.html","attributes":{"data-id":"mcp_access_policies_agent_cloud"},"menu":{"hasChildren":false},"tocID":"mcp_access_policies_agent_cloud-d37814e63208","topics":[]}]}};